import subprocess, os, signal
out=subprocess.run(['ps','-eo','pid,ppid,stat,cmd'],capture_output=True,text=True).stdout
for line in out.splitlines():
    if '/bin/bash' in line or 'execute' in line or 'TopicTree' in line or 'uwsbug' in line or 'fuzzing/TopicTree' in line:
        print(line)
        try:
            pid=int(line.split()[0])
            if pid not in (os.getpid(),): os.kill(pid, signal.SIGKILL); print('killed',pid)
        except Exception as e: print(e)
